/* Kiln & Co — see DESIGN.md for the decisions behind these tokens. */

:root {
  /* Wet-clay neutrals, tinted cool toward hue 230 */
  --bg: oklch(0.955 0.006 230);
  --surface: oklch(0.985 0.003 230);
  --footer: oklch(0.90 0.008 230);
  --ink: oklch(0.24 0.02 255);
  --muted: oklch(0.46 0.02 250);
  --rule: oklch(0.62 0.015 240);
  /* Cobalt underglaze: actions only */
  --accent: oklch(0.45 0.16 264);
  --accent-press: oklch(0.38 0.15 264);
  --ring: var(--accent);
  /* Test-tile materials: the signature, never used for text */
  --bisque: oklch(0.86 0.03 55);
  --bisque-edge: oklch(0.74 0.035 50);
  --celadon: oklch(0.74 0.07 170);
  --celadon-pool: oklch(0.58 0.08 175);
  --shino: oklch(0.82 0.08 70);
  --shino-pool: oklch(0.66 0.12 45);
  --tenmoku: oklch(0.30 0.05 45);
  --tenmoku-pool: oklch(0.45 0.09 45);
  --peg: oklch(0.32 0.03 60);

  --font-display: "Young Serif", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --font-body: "Hanken Grotesk", system-ui, -apple-system, "Segoe UI", sans-serif;

  /* Type scale, ratio 1.25 */
  --step--1: 0.875rem;
  --step-0: 1.0625rem;
  --step-1: 1.25rem;
  --step-2: 1.5625rem;
  --step-3: clamp(1.75rem, 1.4rem + 1.6vw, 2.45rem);
  --step-5: clamp(2.6rem, 1.6rem + 4.4vw, 4.75rem);

  --space-xs: 0.5rem;
  --space-s: 0.75rem;
  --space-m: 1.5rem;
  --space-l: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6.5rem;

  --page: 72rem;
  --gutter: clamp(1.25rem, 4vw, 3rem);
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}

