  width: 100%;
  height: 100%;
  min-height: 12rem;
  border-radius: 0.25rem;
  background:
    repeating-radial-gradient(circle at 50% 55%, transparent 0 0.9rem, oklch(0.64 0.012 235 / 0.35) 0.9rem 0.98rem),
    linear-gradient(160deg, oklch(0.80 0.012 235), oklch(0.70 0.015 240));
  overflow: hidden;
}
.ph--hero { aspect-ratio: 5 / 4; height: auto; }
.ph--43 { aspect-ratio: 4 / 3; height: auto; }
.ph--wide { aspect-ratio: 21 / 9; height: auto; }

.ph-note {
  margin: var(--space-s);
  padding: 0.3rem 0.6rem;
  background: var(--surface);
  color: var(--ink);
  font-size: var(--step--1);
  line-height: 1.35;
  border-radius: 0.25rem;
}

/* ---------- Signature: the glaze test tile ----------
   A fired test tile: bisque body, a punched hanging hole, glaze over the top
   that pools darker at its lip, a raw clay band at the bottom carrying the name. */

.tile {
  --w: 6.5rem;
  --h: 9rem;
  --glaze: var(--celadon);
  --pool: var(--celadon-pool);
  --glaze-depth: 58%;
  --hole-y: 0.95rem;

  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  width: var(--w);
  min-height: var(--h);
  padding: 0.55rem 0.6rem 0.6rem;
  background: var(--bisque);
  color: var(--ink);
  text-decoration: none;
  border-radius: 0.7rem 0.7rem 0.4rem 0.4rem;
  box-shadow:
    inset 0 -2px 0 var(--bisque-edge),
    0 0.35rem 0.6rem -0.2rem oklch(0.24 0.02 255 / 0.35);
  -webkit-mask: radial-gradient(circle at 50% var(--hole-y), transparent 0.32rem, #000 0.36rem);
  mask: radial-gradient(circle at 50% var(--hole-y), transparent 0.32rem, #000 0.36rem);
  transform-origin: 50% var(--hole-y);
}

.tile::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: var(--glaze-depth);
  background:
    linear-gradient(115deg, oklch(1 0 0 / 0.38) 0 18%, transparent 34%),
    linear-gradient(to bottom, var(--glaze) 45%, var(--pool));
  /* Uneven drip line where the dipped glaze stopped */
  border-radius: 0.7rem 0.7rem 46% 58% / 0.7rem 0.7rem 16% 24%;
}

.tile--celadon { --glaze: var(--celadon); --pool: var(--celadon-pool); }
.tile--shino { --glaze: var(--shino); --pool: var(--shino-pool); }
.tile--tenmoku { --glaze: var(--tenmoku); --pool: var(--tenmoku-pool); }

.tile-label {
  position: relative;
  font-size: var(--step--1);
  font-weight: 700;
  line-height: 1.2;
}
.tile-price {
  display: block;
  font-family: var(--font-display);
  font-weight: 400;
  font-size: var(--step-1);
  margin-top: 0.15rem;
}

/* The rail the hero tiles hang from: a batten with pegs */
.rail {
  position: absolute;
  left: clamp(-1.5rem, -2vw, 0rem);
  bottom: 0;
  display: flex;
  gap: var(--space-s);
  margin: 0;
  padding: 0 var(--space-s);
  list-style: none;
}
.rail::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0.45rem;
  height: 0.5rem;
  background: var(--peg);
  border-radius: 0.2rem;
  box-shadow: 0 2px 3px oklch(0.24 0.02 255 / 0.3);
}
.rail li { position: relative; }
.rail li::before { /* the peg, seen through the punched hole */
  content: "";
  position: absolute;
  left: 50%;
  top: calc(0.95rem - 0.22rem);
  width: 0.44rem;
  height: 0.44rem;
  margin-left: -0.22rem;
  border-radius: 50%;
  background: oklch(0.2 0.02 60);
}
.rail .tile {
  animation: hang 760ms var(--ease-out) both;
  transition: transform 200ms var(--ease-out), box-shadow 200ms var(--ease-out);
}
.rail li:nth-child(2) .tile { animation-delay: 90ms; }
.rail li:nth-child(3) .tile { animation-delay: 180ms; }

@keyframes hang {
  from { transform: rotate(-8deg); }
  55% { transform: rotate(2.5deg); }
  to { transform: rotate(0deg); }
}

@media (hover: hover) {
  .rail .tile:hover {
    transform: translateY(-3px);
    box-shadow:
      inset 0 -2px 0 var(--bisque-edge),
      0 0.7rem 1rem -0.3rem oklch(0.24 0.02 255 / 0.4);
  }
}
.rail .tile:active { transform: translateY(1px); }
.rail .tile:focus-visible { outline-offset: 4px; }
/* The mask would clip the focus ring, so draw the ring on the list item instead */
.rail li:has(.tile:focus-visible)::after {
  content: "";
  position: absolute;
  inset: -5px;
  border: 3px solid var(--ring);
  border-radius: 0.9rem 0.9rem 0.6rem 0.6rem;
  pointer-events: none;
}

/* ---------- Workshops ---------- */

.workshops {
  max-width: var(--page);
  margin: 0 auto;
  padding: 0 var(--gutter) var(--space-2xl);
  scroll-margin-top: var(--space-m);
}

.section-head {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 6fr);
  gap: var(--space-s) var(--space-l);
  align-items: end;
  margin-bottom: var(--space-l);
}
.section-head h2 {
  font-size: var(--step-3);
  line-height: 1.1;
}
.section-head p { color: var(--muted); max-width: 36rem; }

.workshop {
  display: grid;
  grid-template-columns: 7.5rem minmax(0, 1fr) 14rem;
  gap: var(--space-m) var(--space-l);
  align-items: start;
  padding-block: var(--space-l);
  border-top: 1px solid var(--rule);
  scroll-margin-top: var(--space-m);
}

.tile--row {
  --w: 6rem;
  --h: 8rem;
  justify-content: flex-end;
}

.workshop h3 {
  font-size: var(--step-2);
  line-height: 1.15;
  margin-bottom: var(--space-s);
}
.workshop-body > p { max-width: 38rem; }

.facts {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 0.35rem var(--space-m);
  margin: var(--space-m) 0 0;
  font-size: var(--step--1);
  line-height: 1.5;
}
.facts dt { color: var(--muted); font-weight: 500; }
.facts dd { margin: 0; font-weight: 500; }

.workshop-book {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--space-s);
}

.price {
  font-family: var(--font-display);
  font-size: var(--step-3);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.price span {
  display: block;
  margin-top: 0.35rem;
  font-family: var(--font-body);
  font-size: var(--step--1);
  color: var(--muted);
}

.booking-note {
  padding-top: var(--space-l);
  border-top: 1px solid var(--rule);
  max-width: 44rem;
  overflow-wrap: anywhere;
}

/* ---------- Studio ---------- */

.studio {
  max-width: var(--page);
  margin: 0 auto;
  padding: 0 var(--gutter) var(--space-2xl);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 2.2fr);
  gap: var(--space-l);
  align-items: start;
  scroll-margin-top: var(--space-m);
}

.studio-copy { position: sticky; top: var(--space-l); }
.studio-copy h2 {
  font-size: var(--step-3);
  line-height: 1.1;
  margin-bottom: var(--space-m);
}
.studio-copy p + p { margin-top: var(--space-s); }

.gallery {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  gap: var(--space-m);
}

.shot { margin: 0; display: flex; flex-direction: column; }
.shot--tall { grid-row: span 2; }
.shot--tall .ph { flex: 1; min-height: 20rem; }
.shot--wide { grid-column: 1 / -1; }

figcaption {
  margin-top: var(--space-xs);
  font-size: var(--step--1);
  color: var(--muted);
}

/* ---------- Footer ---------- */

.site-footer {
  background: var(--footer);
  scroll-margin-top: 0;
}

.footer-inner {
  max-width: var(--page);
  margin: 0 auto;
  padding: var(--space-xl) var(--gutter) var(--space-l);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(0, 1fr);
  gap: var(--space-l);
  align-items: start;
}

/* The unglazed plaque: same tile, no glaze, it carries the address */
.tile--plaque {
  --w: auto;
  --h: auto;
  --hole-y: 1rem;
  min-width: 15rem;
  padding: 2.4rem 1.5rem 1.4rem;
  font-style: normal;
  line-height: 1.5;
  gap: 0.1rem;
}
.tile--plaque::before { content: none; }
.tile--plaque h2 {
  font-size: var(--step-2);
  margin-bottom: var(--space-xs);
}

.footer-col h3 {
  font-size: var(--step-1);
  margin-bottom: var(--space-s);
}
.footer-col p + p { margin-top: var(--space-xs); }
.footer-col p { overflow-wrap: anywhere; }

.colophon {
  max-width: var(--page);
  margin: 0 auto;
  padding: 0 var(--gutter) var(--space-l);
  font-size: var(--step--1);
  color: var(--muted);
}

/* ---------- Responsive ---------- */

@media (max-width: 60rem) {
  .hero,
  .section-head,
  .studio { grid-template-columns: minmax(0, 1fr); }
  .hero { padding-top: var(--space-l); gap: var(--space-l); }
  .studio-copy { position: static; }
  .workshop { grid-template-columns: 6.5rem minmax(0, 1fr); }
  .workshop-book {
    grid-column: 2;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
  }
  .footer-inner { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .tile--plaque { grid-column: 1 / -1; justify-self: start; }
}

@media (max-width: 36rem) {
  .rail { left: 0; gap: var(--space-xs); padding-inline: var(--space-xs); }
  .rail .tile { --w: 5.6rem; --h: 8rem; }
  .workshop { grid-template-columns: minmax(0, 1fr); }
  .tile--row { --w: 4.5rem; --h: 6rem; }
  .tile--row .tile-label { font-size: 0.75rem; }
  .workshop-book { grid-column: 1; }
  .gallery { grid-template-columns: minmax(0, 1fr); }
  .shot--tall { grid-row: auto; }
  .shot--tall .ph { aspect-ratio: 4 / 5; min-height: 0; }
  .footer-inner { grid-template-columns: minmax(0, 1fr); }
  .tile--plaque { min-width: 0; width: 100%; }
}

@media (pointer: coarse) {
  .nav-links a { padding-block: 0.75rem; }
}

/* Reduced motion: tiles hang at rest, nothing moves under the pointer.
   Colour and underline state changes stay. */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .rail .tile { animation: none; transition: box-shadow 150ms linear; }
  .rail .tile:hover,
  .rail .tile:active { transform: none; }
  .btn { transition: background-color 150ms linear; }
  .btn:active { transform: none; }
}

@media (forced-colors: active) {
  .tile { border: 1px solid CanvasText; }
  .ph { border: 1px solid CanvasText; }
}

